export function visit(schema: $ZodType, rewrite: Visitor): $ZodType {
  type Node = { schema: $ZodType; def: any; edges: $ZodType[]; index: number; low: number; active: boolean };
  const nodes = new Map<$ZodType, Node>();
  const results = new Map<$ZodType, $ZodType>();
  const stack: Node[] = [];
  let index = 0;

  function mapDef(s: $ZodType, map: (s: $ZodType) => $ZodType): any {
    const d = s._zod.def as any;
    const next = { ...d };
    const field = (key: string) => { if (d[key]) next[key] = map(d[key]); };
    switch (d.type) {
      case "object":
        next.shape = Object.fromEntries(Object.entries(d.shape).map(([k, v]) => [k, map(v as $ZodType)]));
        field("catchall");
        break;
      case "array": field("element"); break;
      case "tuple": next.items = d.items.map(map); field("rest"); break;
      case "record": case "map": field("keyType"); field("valueType"); break;
      case "set": field("valueType"); break;
      case "union": next.options = d.options.map(map); break;
      case "intersection": field("left"); field("right"); break;
      case "optional": case "nullable": case "default": case "prefault":
      case "nonoptional": case "catch": case "readonly": case "promise": case "success":
        field("innerType"); break;
      case "pipe": field("in"); field("out"); break;
      case "function": field("input"); field("output"); break;
      case "lazy": {
        const inner = map((s._zod as any).innerType);
        delete next._cachedInner;
        next.getter = () => inner;
        break;
      }
    }
    return next;
  }
  function walk(s: $ZodType): void {
    if (nodes.has(s)) return;
    const n: Node = { schema: s, def: undefined, edges: [], index, low: index++, active: true };
    nodes.set(s, n);
    stack.push(n);
    n.def = mapDef(s, (child) => { n.edges.push(child); return child; });
    for (const child of n.edges) {
      if (!nodes.has(child)) { walk(child); n.low = Math.min(n.low, nodes.get(child)!.low); }
      else if (nodes.get(child)!.active) n.low = Math.min(n.low, nodes.get(child)!.index);
    }
    if (n.low !== n.index) return;
    const component: Node[] = [];
    let member: Node;
    do { member = stack.pop()!; member.active = false; component.push(member); } while (member !== n);
    const cyclic = component.length > 1 || n.edges.includes(s);
    const refs = new Map<$ZodType, $ZodType>();
